#!/usr/bin/python
"""Reconcile invoice totals with payments, using integer cents only."""

import csv
import os
import re
import tempfile

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CENT_AMOUNT = re.compile(r"^[+-]?[0-9]+$")


def parse_cents(value):
    """Return an integer cent amount; reject decimals and other malformed data."""
    text = (value or "").strip()
    if not CENT_AMOUNT.match(text):
        raise ValueError("malformed_amount")
    return int(text)


def load_invoices(path):
    invoices = {}
    order = []
    with open(path, newline="") as source:
        reader = csv.DictReader(source)
        required = {"invoice_id", "total_cents"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError("invoices.csv must contain invoice_id and total_cents")
        for line_number, row in enumerate(reader, 2):
            invoice_id = (row.get("invoice_id") or "").strip()
            if not invoice_id:
                raise ValueError("invoices.csv line %d has an empty invoice_id" % line_number)
            if invoice_id in invoices:
                raise ValueError("invoices.csv line %d duplicates invoice_id %s" % (line_number, invoice_id))
            try:
                invoices[invoice_id] = parse_cents(row.get("total_cents"))
            except ValueError:
                raise ValueError("invoices.csv line %d has a malformed total_cents" % line_number)
            order.append(invoice_id)
    return invoices, order


def load_payments(path, balances):
    rejected = []
    seen_payment_ids = set()
    with open(path, newline="") as source:
        reader = csv.DictReader(source)
        required = {"payment_id", "invoice_id", "amount_cents"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError("payments.csv must contain payment_id, invoice_id and amount_cents")
        for row in reader:
            payment_id = (row.get("payment_id") or "").strip()
            invoice_id = (row.get("invoice_id") or "").strip()
            amount_text = (row.get("amount_cents") or "").strip()

            if not payment_id:
                reason = "missing_payment_id"
            elif payment_id in seen_payment_ids:
                reason = "duplicate_payment_id"
            elif invoice_id not in balances:
                reason = "unknown_invoice_id"
            else:
                try:
                    amount = parse_cents(amount_text)
                except ValueError:
                    reason = "malformed_amount"
                else:
                    balances[invoice_id] -= amount
                    reason = None

            if payment_id:
                seen_payment_ids.add(payment_id)
            if reason:
                rejected.append({
                    "payment_id": payment_id,
                    "invoice_id": invoice_id,
                    "amount_cents": amount_text,
                    "reason": reason,
                })
    return rejected


def publish_csv(path, fieldnames, rows):
    fd, temporary = tempfile.mkstemp(prefix=".%s." % os.path.basename(path), dir=BASE, text=True)
    try:
        with os.fdopen(fd, "w", newline="") as target:
            writer = csv.DictWriter(target, fieldnames=fieldnames, lineterminator="\n")
            writer.writeheader()
            writer.writerows(rows)
            target.flush()
            os.fsync(target.fileno())
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def main():
    balances, invoice_order = load_invoices(os.path.join(BASE, "invoices.csv"))
    rejected = load_payments(os.path.join(BASE, "payments.csv"), balances)
    balance_rows = [
        {"invoice_id": invoice_id, "outstanding_cents": balances[invoice_id]}
        for invoice_id in invoice_order
    ]
    publish_csv(
        os.path.join(BASE, "balances.csv"),
        ["invoice_id", "outstanding_cents"],
        balance_rows,
    )
    publish_csv(
        os.path.join(BASE, "rejected.csv"),
        ["payment_id", "invoice_id", "amount_cents", "reason"],
        rejected,
    )


if __name__ == "__main__":
    main()
PYEOF
